const NOVENE_PAGES = {
"changelogs": atob(""),
"credits": atob(""),
"history": atob(""),
};
function pageDoc(name) { return NOVENE_PAGES[name] || ""; }
function newBrowserTab(url){const id="t"+ ++tabSeq;const iframe=document.createElement("iframe");iframe.className="faizframe";iframe.setAttribute("frameborder","0");iframe.setAttribute("title","novene browser");pageCont.insertBefore(iframe,loaderEl);const tab={id:id,kind:"browser",title:"New Tab",url:"",favicon:null,iframe:iframe,sframe:null,page:null,lastHref:"",firstPoll:true};tab.el=makeTabEl(tab);tabBar.insertBefore(tab.el,plusBtn);const earlyNv=url?parseNoveneUrl(url):null;const earlyPage=earlyNv&&earlyNv.view?pageForView(earlyNv.view):null;if(earlyPage){tab.page=earlyPage;iframe.classList.add("faizframe-page");iframe.removeAttribute("src");iframe.setAttribute("srcdoc",pageDoc(earlyPage))}else if(nve){tab.sframe=nve.createFrame(iframe)}tabs.set(id,tab);createIcons();if(url)navigate(id,url);return tab}
function showPage(tab,view,page,canon){launchMode=null;aiMode=false;homeView.classList.add("hidden");aiView.classList.remove("active");setView.classList.remove("active");if(launchView)launchView.classList.remove("active");tabs.forEach(t=>{t.el.classList.remove("active");if(t.kind==="browser")t.iframe.classList.remove("active")});tab.el.classList.add("active");if(!tab.page||tab.iframe.getAttribute("data-novene-page")!==page){const fresh=document.createElement("iframe");fresh.className="faizframe faizframe-page";fresh.setAttribute("frameborder","0");fresh.setAttribute("title","novene "+view);if(tab.iframe)tab.iframe.remove();pageCont.insertBefore(fresh,loaderEl);tab.iframe=fresh;tab.sframe=null;tab.page=page;fresh.removeAttribute("src");fresh.setAttribute("srcdoc",pageDoc(page));fresh.setAttribute("data-novene-page",page)}tab.iframe.classList.add("active");activeId=tab.id;urlInput.value=canon;urlInput.placeholder="Search or enter address...";setUrlIcon(view==="credits"?"heart":view==="history"?"history":"scroll-text");railButtons.forEach(b=>{const map={changelogs:"chBtn",credits:"crBtn",history:"hiBtn"};b.classList.toggle("active",b.id===map[view])});updateNavButtons()}